<?php declare(strict_types=1);session_start();require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();function portal_user():?array{return $_SESSION['portal_user']??null;}function portal_require():array{$u=portal_user();if(!$u){header('Location: /distinguished-web-services/portal/login.php');exit;}return $u;}function portal_login(int $id):void{$_SESSION['portal_user']=['id'=>$id];}function portal_logout():void{$_SESSION=[];if(ini_get('session.use_cookies')){$p=session_get_cookie_params();setcookie(session_name(),'',['expires'=>time()-42000,'path'=>$p['path'],'domain'=>$p['domain'],'secure'=>$p['secure'],'httponly'=>$p['httponly']]);}session_destroy();}